import{_ as e,o as d,c as p,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Matrix-Elementwise-Binary-Operators.md","filePath":"manual-zh/Matrix-Elementwise-Binary-Operators.md","lastUpdated":1785684581000}'),a={name:"manual-zh/Matrix-Elementwise-Binary-Operators.md"};function r(c,t,l,i,n,s){return d(),p("div",null,[...t[0]||(t[0]=[o('<h4 id="_16-4-1-5-elementwise-binary-operators" tabindex="-1">16.4.1.5 Elementwise Binary Operators <a class="header-anchor" href="#_16-4-1-5-elementwise-binary-operators" aria-label="Permalink to &quot;16.4.1.5 Elementwise Binary Operators&quot;">​</a></h4><p>逐元素二元运算符要求它们的操作数是具有相同维度的矩阵。或者，如果一个操作数是标量，则其值被视为被复制到其他操作数的维度。结果是一个与操作数大小相同的矩阵，其中每个元素是运算符作用于操作数对应元素的结果。</p><p>逐元素二元运算符列出如下。</p><ul><li>算术运算符，用于常见的算术运算：</li></ul><p><code>+</code></p><p>加法。</p><p><code>-</code></p><p>减法。</p><p><code>*</code></p><p>乘法，如果一个操作数是标量。（否则这是矩阵乘法，如下所述。）</p><p><code>/</code> 或 <code>&amp;/</code></p><p>除法。</p><p><code>&amp;*</code></p><p>乘法。</p><p><code>&amp;**</code></p><p>乘方。</p><ul><li>关系运算符，比较为真时结果为 1，为假时结果为 0：</li></ul><p><code>&lt;</code> 或 <code>LT</code></p><p>小于。</p><p><code>&lt;=</code> 或 <code>LE</code></p><p>小于或等于。</p><p><code>=</code> 或 <code>EQ</code></p><p>等于。</p><p><code>&gt;</code> 或 <code>GT</code></p><p>大于。</p><p><code>&gt;=</code> 或 <code>GE</code></p><p>大于或等于。</p><p><code>&lt;&gt;</code> 或 <code>~=</code> 或 <code>NE</code></p><p>不等于。</p><ul><li>逻辑运算符，将正操作数视为真，非正操作数视为假。假时产生 0，真时产生 1：</li></ul><p><code>AND</code></p><p>如果两个操作数都为真则为真。</p><p><code>OR</code></p><p>如果至少一个操作数为真则为真。</p><p><code>XOR</code></p><p>如果恰好一个操作数为真则为真。</p><p>示例：</p><table tabindex="0"><thead><tr><th>1 + 2</th><th>⇒</th><th>3</th></tr></thead><tbody><tr><td>1 + {3; 4}</td><td>⇒</td><td>{4; 5}</td></tr><tr><td>{66, 77; 88, 99} + 5</td><td>⇒</td><td>{71, 82; 93, 104}</td></tr><tr><td>{4, 8; 3, 7} + {1, 0; 5, 2}</td><td>⇒</td><td>{5, 8; 8, 9}</td></tr><tr><td>{1, 2; 3, 4} &lt; {4, 3; 2, 1}</td><td>⇒</td><td>{1, 1; 0, 0}</td></tr><tr><td>{1, 3; 2, 4} &gt;= 3</td><td>⇒</td><td>{0, 1; 0, 1}</td></tr><tr><td>{0, 0; 1, 1} AND {0, 1; 0, 1}</td><td>⇒</td><td>{0, 0; 0, 1}</td></tr></tbody></table>',38)])])}const h=e(a,[["render",r]]);export{_ as __pageData,h as default};
